	if len(os.Args) < 2 {
		return
	}

	N, err := strconv.Atoi(os.Args[1])
	if err != nil {
		return
	}

	for i := 2; i <= N; i++ {
		if isPrime(i) {
			fmt.Println(i)
		}
	}
}
